from functools import lru_cache

def find_kth_label(length, rooms, label):
    @lru_cache(maxsize=None)
    def min_take(length, k):
        if k == 0:
            return ''
        if length <= 1:
            return label[-k]
        min_name = ''
        for i in range(1, length):
            sub_label = label[-i]
            min_name_min_take = min_take(i, k - 1)
            if sub_label < min_name_min_take[-i + 1]:
                min_name = sub_label + min_name_min_take
                break
        return min_name

    return min_take(length, rooms)

