def factorize(n):
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def inverse_mod(x, mod):
    y = pow(x, mod - 2, mod)
    return y

def multinomial_coefficient(a, b):
    factors = {}
    for x in factorize(a + b):
        if x in factors:
            factors[x] += 1
        else:
            factors[x] = 1
    numerator = 1
    for x in factors:
        numerator *= multimult(x, 1, factors[x])
    denominator = 1
    for x in factors:
        factorial = multimult(x, 1, factors[x] - 1)
        denominator *= factorial
        inv_factorial = inverse_mod(factorial, mod)
        denominator *= inv_factorial
    return numerator * inverse_mod(denominator, mod)

def multimult(x, start, n):
    if n == 0:
        return 1
    if n == 1:
        return x
    else:
        return (x ** n) % mod * multimult(x, start, n - 1) % mod

