import sys

def decrypt_binary_matrix(matrix):
    n = len(matrix[0]) // 4
    bit_map = []
    for row in matrix:
        bits = []
        for hex_num in row:
            digits = hex_num.decode("hex")
            bits.extend(digits)
        bit_map.append(bits)
    return bit_map

def calculate_dis(bit_map):
    n = len(bit_map[0])
    total_dis = 0
    for i in range(n):
        for j in range(i):
            if bit_map[i][j]:
                total_dis += (i + 1) * (j + 1) * 2
            else:
                total_dis -= (i + 1) * (j + 1)
    for i in range(n):
        for j in range(i + 1, n):
            if bit_map[i][j]:
                total_dis += 2 + ((i + 1) * (j + 1))
            else:
                total_dis -= 2
    return total_dis

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    bit_map = [[1 if x != "0" else 0 for x in hex(ord(x)).rstrip("L").lstrip("0")] for x in data[1:]]
    bit_map = decrypt_binary_matrix(bit_map)
    print(calculate_dis(bit_map))

if __name__ == "__main__":
