from heapq import heappush, heappop

def min_hours(n, m, q):
    sets = [0] * (n + 1)
    weapons = [0] * (m + 1)
    synergies = []

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) not in synergies:
                sets[i] = max(sets[i], i + j)
                weapons[j] = max(weapons[j], i)
                synergies.append((i, j))

    heap = []
    # Add combinations that synergize well with both the strongest sets and single weapons
    for synergy in synergies:
        if synergy[0] == n and synergy[1] == m:
            heappush(heap, -synergy[0])
            heappush(heap, -synergy[1])
        elif synergy[0] == n:
            heappush(heap, -synergy[1])
        elif synergy[1] == m:
            heappush(heap, -synergy[0])

    for _ in range(q):
        choice = heappop(heap)
        if choice[0] > n and choice[1] > m:
            attempts = min(choice[0] - n, choice[1] - m) // 2
            weakset, weakweapon = choice, choice
            if choice[0] > n:
                weakset -= attempts
            if choice[1] > m:
                weakweapon -= attempts
            for _ in range(attempts):
                weakset += 1
                weakweapon += 1
                if weakset <= n and weakweapon <= m:
                    heappush(heap, -weakset)
                    heappush(heap, -weakweapon)

    return -heap[0]

