import sys
from collections import defaultdict

def build_tree(num_nodes, edges):
    tree = [[] for _ in range(num_nodes)]
    for u, v in edges:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)
    return tree

def bfs(node, tree, distance):
    dq = [(node, 0)]
    seen = set([node])
    while dq:
        node, d = dq.pop()
        for adj in tree[node]:
            if adj not in seen:
                seen.add(adj)
                dq.append((adj, d+1))
        distance[node] = d

def get_dist(node, root, tree, dist):
    if dist[node] == -1:
        bfs(node, tree, dist)
    return dist[node]

def dfs(node, group, groups, tree, n, dist, groups):
    if not groups:
        return 1
    if len(groups) == 1:
        groups += [group]
        visited[node] = 1
        return 1
    for child in tree[node]:
        if visited[child]:
            continue
        child_dist = get_dist(child, root, tree, dist)
        if child_dist != -1:
            if child_dist > dist[node]:
                dfs(child, group, groups, tree, n, dist, groups)
                continue

    groups.append(group)
    visited[node] = 1
    return dfs(node, [], groups, tree, n, dist, groups)

def solve(n, q, queries):
    tree = build_tree(n)
    visited, distance = [[-1]*n for _ in range(n)], [[-1]*n for _ in range(n)]
    for query_key, group, queries, dist in queries:
        if visited[query_key][group]:
            assert queries == 1
            num_dist = bfs(query_key, tree, distance)
            assert num_dist < dist[query_key]
            if num_dist == dist[query_key]:
                return 0
            queries -= 1

        visited[query_key][group] = 1
        for query_key in range(group, group+queries):
            dfs(query_key, query_key, [], tree, n, distance, [])
        visited[query_key][group] = 0

    return sum((3**group - 1)/(4-1) for _, m, _, _, _, _ in queries) % 1000000007

