    xroot = find_leader(parent, x)
    yroot = find_leader(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def create_nation(n, matrix):
    parent = list(range(n))
    rank = [0] * n
    bipartite = [False] * n
    efficient_centrality = 0

    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j]:
                union_set(parent, rank, i, j)
    found = False
    bi_to_complement = defaultdict(list)

    for i in range(n):
        for j in range(n):
            if not matrix[i][j] and not bipartite[j]:
                bipartite[j] = True
                bi_to_complement[i].append(j)
                bi_to_complement[j].append(i)

