from bisect import insort_left

def calculate_strangeness(array, n):
    record, counted_elements, smallest, largest = {}, {}, float('inf'), float('-inf')

    array.sort()

    for i, num in enumerate(array):
        if num not in counted_elements:
            insort_left(record, num)
            min_deque = record[min(record)]
            min_index, max_index = record[min_deque], record[min_deque]
            del record[min_deque]

            if i % 2 == 1:
                if max_index > min_index:
                    difference = (i - 1 - min_index) // 2 + (i - 1 - max_index) // 2
                else:
                    difference = (i - 1 - min_index + (n % 2 == 1)) // 2 + 1 
            else:
                if min_index > max_index:
                    difference = (min_index - 1 - i-1) // 2 + (min_index - 1 - max_index) // 2
                else:
                    difference = (min_index - 1 - i-1 // 2 + 1)
            consumed = difference + 1

            largest = max(largest, consumed)
        else:
            largest = min(largest, consumed + 1)

    for _ in range(n):
        record[smallest] = smallest
        del record[largest]

    return [smallest - l for l in record.values()]

