MOD = 998244353

def power(a, b):
    # recursive power function
    if b == 0:
        return 1
    half = power(a, b // 2) % MOD
    if b % 2:
        return (a * half * half) % MOD
    else:
        return (half * half) % MOD

def factorial(n):
    # calculate factorial of n
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def combination(n, m):
    # calculate combination C(n, m)
    result = 1
    for i in range(n - m + 1, n + 1):
        result = (result * i) % MOD
    for i in range(1, m + 1):
        result = (result * power(m, MOD - 2)) % MOD
    return result

def count_pairs(n, m):
    # calculate the number of pairs
    return (combination(n, m) * combination(m * 2 - n, m)) % MOD

