from bisect import bisect_left, bisect_right
from typing import List

def solve_max_segment(max_length: int, imps: List[int]) -> int:
    dp = [0] * (max_length + 1)
    dp[0] = -1
    for i, elem in enumerate(imps):
        index = bisect_left(dp, elem + 1)
        if elem >= dp[index]:
            dp[index] += 1
        else:
            if index > 0 and elem < dp[index - 1]:
                dp[index - 1] += 1
            else:
                dp[index] = elem
    for i in range(max_length, 0, -1):
        if dp[i] < 1:
            return i
    return 0

def solve_min_segment(min_length: int, imps: List[int]) -> int:
    dp = [0] * (min_length + 1)
    dp[-1] = -1
    reversed_imp = []
    for i, elem in enumerate(sorted(imps)):
        reversed_imp.append((elem, i))
    mem = {reversed_imp[-1][1]: len(dp)}
    imp_lengths = []
    cache = {}
    for elem, i in reversed_imp[:-1][::-1]:
        index = bisect_left(dp, i - 1)
        if elem < dp[index]:
            dp[index] = elem
        else:
            if index + 1 not in mem:
                dp.append(i)
            else:
                dp.append(max(dp[index], elem + 1))
            mem[elem + 1] = index
        cache[i] = mem[elem + 1]
    for i in range(min_length, 1, -1):
        if dp[i] > 0:
            return i + 1
    return 0

def solve(query: int, imps: List[int], types: List[int]) -> int:
    if query == 1:
        return solve_max_segment(len(imps), imps)
    elif query == 2:
        l, r = types[1], types[2]
        if imps[l] > 0:
            return 0
        for i in range(l + 1, r + 1):
            if imps[i - 1] > 0:
                size_needed = solve_min_segment(i, imps)
                if size_needed < 0 or imps[i] - 1 < imps[methods.get(l, -1)] - 1:
                    return 0
        return 1

