import random
import math

def find_smallest(nums, low, high, target):
    left = low-1  # Initialize left boundary
    right = low-1

    while right < high:
        left = left + 1
        right = right + 1
        pivot = random.randint(left, right)

        # Partition nums array around pivot
        (left, pivot, right) = partition(nums, start_index=left, mid_index=pivot, end_index=right)

        if left >= target:
            if low == target - 1:
                break
            else:
                low = left + 1
                high = pivot-1

        if left > target:
            high = pivot

    return pivot

def partition(nums, start_index, mid_index, end_index):
    pivot = mid_index
    small = start_index

    for large in range(start_index, end_index):
        if nums[large] < nums[pivot]:
            nums[large], nums[small] = nums[small], nums[large]
            small += 1

    nums[end_index], nums[small] = nums[small], nums[end_index]
    return start_index, small, end_index

def guess_pivot(nums, pivot):
    median = math.ceil(len(nums)/2)
    target = len(nums) - 1
    if pivot == target:
        return nums[target]
    else:
        if pivot < median:
            return min(nums[target], nums[pivot])
        else:
            return max(nums[target], nums[pivot])

