from collections import defaultdict

def robot_level(n, m, q, pairs):
    # Initialize a list for armor levels
    armor_levels = range(1, n + 1)
    # Add the starting weapon to the list
    armor_levels.append(1)
    # Initialize a set for weapon tiers
    weapon_tiers = {1}

    for i in armor_levels:
        if pairs.count((i, 1)) >= 1:
            armor_levels.remove(i)
        if pairs.count((i, 1)) >= q - (i-1):
            weapon_tiers.add(1)
            armor_levels.remove(i)
        else:
            break

    # Create a lookup table for weapon tiers
    weapon_tier_weights = defaultdict(int)
    for i in range(1, m + 1, 1):
        if (i, 1) in pairs:
            continue
        weapon_tier_weights[1] += 1
        if i-1 in pairs:
            weapon_tier_weights[1] -= 1

    for i in range(2, m + 1, 1):
        if pairs.count((1, i-1)) >= q - i:
            continue
        weapon_tier_weights[1] -= 1
        weapon_tiers.add(i)
        if pairs.count((1, i-1)) >= q - (i-1):
            weapon_tier_weights[1] += 1
        elif weapon_tier_weights[1] >= 0:
            weapon_tier_weights[i] += 1
        else:
            weapon_tier_weights[i-1] -= 1

    # Initialize total rounds for each tier
    tier_rounds = [0] * (m + 1)

    for weight in weapon_tier_weights.values():
        if weight:
            tier_rounds[weight - 1] += 1

    for i in armor_levels[::-1]:
        armor_level_weight = (armor_levels.index(i) + 1) * len(armor_levels) - len(armor_levels) - 1 + q
        if armor_level_weight not in weapon_tier_weights:
            armor_level_weight += 1
        tier_rounds[armor_level_weight - 1] += len(armor_levels) + 1

    return min(tier_rounds)

