from fractions import Fraction

def calculate_probability(n, cache_size, prob_list):
    q = 1000000000000
    cache = [Fraction(0,1) for _ in range(cache_size)]
    for i in range(n):
        pi = prob_list[i]
        for prev in cache[-cache_size:]:
            prev_pair = pi * prev / (1 - pi)
            for i, v in enumerate(cache):
                if v < prev_pair:
                    cache[i] -= v / prev_pair
        cache.sort()
        for v in cache:
            ahead_score, ahead_common = 1, 1
            late_score, rare_common = 1, 1
            for elt in range(i + 1, min(i + 1 + q, len(cache))):
                elt_ratio = cache[elt] / ahead_common
                ahead_score *= (1 - (1 - cache[elt]) * elt_ratio)
                ahead_common *= (1 - elt_ratio)
                for elt_lim in range(i + 1):
                    if elt_lim == 0:
                        late_score *= (1 - cache[elt_lim])
                    else:
                        rare_common *= (1 - cache[elt_lim])
            for elt_lim in range(len(cache) - max(i + 1 - q, 0)):
                if elt_lim == 0:
                    late_score *= (1 - cache[elt_lim])
                else:
                    rare_common *= (1 - cache[elt_lim])
            for elt_lim in range(len(cache)):
                if elt_lim == cache_size:
                    rare_common *= (1 - cache[elt_lim])
                else:
                    late_score *= cache[elt_lim]
            break
    return cache


