from collections import defaultdict

def min_cables_for_janitor(n, m, cables):
    # Create adjacency list for input cables 
    adj_list = [[] for _ in range(n + 1)]
    for a, b in cables:
        adj_list[a].append(b)
        adj_list[b].append(a)
    ans = 0

    def find_cycle(a):
        color = [False] * (n + 1)
        stack, path = [a], [a]
        color[a] = True
        while stack:
            node = stack.pop()
            for neighbor in adj_list[node]:
                if color[neighbor]:
                    for p in path.copy():
                        if p != neighbor:
                            if not path:
                                ans += 2
                            ans += 1
                        else:
                            ans += 2
                    return True
                if not color[neighbor]:
                    color[neighbor] = True
                    stack.append(neighbor)
                    path.append(neighbor)
                    ans += 1
        return False

    def dfs(a, b):
        color = [False] * (n + 1)
        stack, res = [a], []
        color[a] = True
        while stack:
            node = stack.pop()
            for neighbor in adj_list[node]:
                if color[neighbor]:
                    res.append((neighbor, node))
                    break
                if color[neighbor]:
                    res.append((node, neighbor))
                if not color[neighbor]:
                    color[neighbor] = True
                    stack.append(neighbor)
                    res.append((node, neighbor))
        return res, ans

    has_cycle, cycles = dfs(1, 1), [[]]
    if has_cycle:
        return dfs(1, 1)
    for node in cycles[0]:
        if not cycles[0]:
            break
        for neighbor in adj_list[node]:
            if not cycles[0]:
                cycles[0] = []
            if neighbor not in cycles[0]:
                cycles[0].append(neighbor)
                break
            else:
                cycles[0].append(node)
                cycles.append([])
    # connect groups of two
    down_left, down_right = defaultdict(list), defaultdict(list)
    col = defaultdict(int)
    for i in range(1, n + 1):
        for node in down_left[down_right[node]]:
            node1, node2 = cycles[node]
            col[node1], col[node2] += 1
            if ((node1, node2) not in down_left[node]) and ((node2, node1) not in down_left[node]):
                down_right[node].append(node1)
                down_right[node].append(node2)
    out, out2 = dfs(1, 1), []
    for node in out:
        out.remove(node)
        node1, node2 = cycles[node]
        while col[node1] < 2 or col[node2] < 2:
            for neighbor in adj_list[node]:
                if neighbor not in out:
                    col[neighbor] -= 1
                    out.append(neighbor)
                    node1, col[node1] = (node1, neighbor) if col[node1] == 2 else (node2, node1)
                    node2, col[node2] = (node2, neighbor) if node1 not in out else (node1, node2)
                    break
        col[out[-1]] -= 1
        col[node] = 0
        out.pop(-1)
        out.append(node1)
        del adj_list[node]
        adj_list[node1].extend(out)
        out = out2
    # return our direction of data flow
    out = [max(x, y) for x, y in out]
    for i, (x, y) in enumerate(out):
        out[i] = (x, y)
    return ans, out

